using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ShrineRewardLocation", menuName = "Data/Map/Shrine Reward Location")]
public class ShrineRewardLocation : RewardLocation
{
	[Header("Anomaly Level")]
	[SerializeField]
	private DifficultyLevel anomalyLevel;

	[SerializeField]
	private ClearingReward brokenShrineClearingReward;

	public override ClearingReward GetClearingReward()
	{
		if (ReferenceSingleton<RunModifiersManager>.Instance.HeartModificationRunModifier != null)
		{
			return ReferenceSingleton<RunModifiersManager>.Instance.HeartModificationRunModifier.BrokenShrineClearingReward;
		}
		if (anomalyLevel.IsBrokenShrinesDifficultyLevelActive())
		{
			return brokenShrineClearingReward;
		}
		return clearingReward;
	}
}
